import csv
import io
import posixpath
from datetime import date, datetime
from decimal import Decimal, ROUND_HALF_UP

def page(p):
    start=(p['page']-1)*p['size']
    return p['items'][start:start+p['size']]

def latest(p):
    return list({r['id']:r for r in p}.values())

