from . import policy, core

OPERATIONS = {
    'versions': policy.versions,
    'csv_row': policy.csv_row,
    'merge': policy.merge,
    'page': core.page,
    'latest': core.latest,
}

def handle(request):
    return OPERATIONS[request['operation']](request['payload'])

